{
  "tool": "evaluate",
  "args": {
    "name": "main_offset_0.5",
    "hypothesis": "Add a positive offset to the main engine (action 2) logits to increase its selection frequency, compensating for the reduced main thrust in the weak_main physics while keeping other actions unchanged.",
    "ops": [
      {
        "op": "output_affine",
