{
  "tool": "evaluate",
  "args": {
    "name": "scale_hv_main_offset_0.15",
    "hypothesis": "Scale the height and vertical velocity observations by 1.15 so the controller perceives the lander as higher and descending faster, prompting earlier braking. Add a modest +0.15 bias to the main engine logit to compensate for the 25% thrust reduction, aiming to improve landing timing and attitude control while preserving overall solution success.",
    "ops": [
      {
        "op": "input_affine",
        "scale": [1, 1.15, 1, 1.15, 1, 1, 1, 1]
      },
      {
        "op": "output_affine",
        "scale": [1, 1, 1, 1],
        "offset": [0, 0, 0.15, 0],
        "permutation": [0, 1, 2, 3]
      }
    ]
  }
}

{
  "tool": "evaluate",
  "args": {
    "name": "scale_hv_ang_main_offset_0.2",
    "hypothesis": "Scale height, vertical velocity, body angle, and angular velocity by 1.2 to make the controller perceive the lander as higher, falling faster, and tilting more, prompting earlier main thrust and stronger attitude corrections. Add a +0.2 bias to the main engine logit to compensate for the 25% thrust reduction.",
