      }
    ]
  }
}

{
  "tool": "evaluate",
  "args": {
    "name": "scale_hv_ang_main_side_offset",
    "hypothesis": "Scale height, vertical velocity, body angle, and angular velocity by 1.2 to make the controller perceive a higher altitude, faster descent, and larger tilt, prompting earlier main thrust and stronger attitude corrections. Add a modest +0.25 bias to the main engine logit and small +0.05 biases to both side‑engine logits to encourage side thrust for better horizontal positioning and attitude control, while keeping the off‑engine action unchanged.",
    "ops": [
      {
        "op": "input_affine",
        "scale": [1, 1.2, 1, 1.2, 1.2, 1.2, 1, 1]
      },
      {
        "op": "output_affine",
        "scale": [1, 1, 1, 1],
        "offset": [0, 0.05, 0.25, 0.05],
        "permutation": [0, 1, 2, 3]
      }
    ]
  }
}

{
  "tool": "evaluate",
  "args": {
    "name": "small_side_main_bias",
    "hypothesis": "Add a small positive bias to the left and right side engine logits (+0.05) and a modest bias to the main engine (+0.1) to encourage earlier and more balanced thrust, helping compensate for the weaker main thrust and improve horizontal positioning without significantly affecting overall stability.",
    "ops": [
      {
        "op": "output_affine",
        "scale": [1, 1, 1, 1],
        "offset": [0, 0.05, 0.1, 0.05],
        "permutation": [0, 1, 2, 3]
      }
    ]
  }
}

{
  "tool": "evaluate",
  "args": {
    "name": "scale_all_dyn_bias_main_side",
    "hypothesis": "Scale height, vertical velocity, horizontal velocity, body angle, and angular velocity by ~1.25–1.2 to make the lander appear higher, falling faster, and more tilted, prompting earlier main thrust and side thrust. Add modest biases (+0.1) to side engine logits and a larger bias (+0.25) to the main engine logit to compensate for reduced main thrust and improve horizontal positioning.",
    "ops": [
      {
        "op": "input_affine",
        "scale": [1, 1.25, 1.2, 1.25, 1.2, 1.2, 1, 1]
