      {
        "op": "output_affine",
        "scale": [1, 1, 1, 1],
        "offset": [0, 0.1, 0.25, 0.1],
        "permutation": [0, 1, 2, 3]
      }
    ]
  }
}

{
  "tool": "evaluate",
  "args": {
    "name": "scale_all_features_bias_main_side",
    "hypothesis": "Increase sensitivity to horizontal position, altitude, velocities, and attitude by scaling the corresponding observations (x, height, horizontal velocity, vertical velocity, body angle, angular velocity). This should cause the controller to fire side engines earlier to correct lateral drift and fire the main engine sooner to compensate for reduced thrust. Add modest positive biases to the side‑engine logits (+0.1) and a larger bias to the main‑engine logit (+0.2) to further encourage timely thrust without overwhelming the policy.",
