      {
        "op": "input_affine",
        "scale": [1.2, 1.3, 1.5, 1.3, 1.2, 1.2, 1, 1]
      },
      {
        "op": "output_affine",
        "scale": [1, 1, 1, 1],
        "offset": [0, 0.1, 0.2, 0.1],
        "permutation": [0, 1, 2, 3]
      }
    ]
  }
}

